import React, { useState, useEffect } from "react";
import "./Test.css"; // Import the CSS file

const Test = () => {
    const [topic, setTopic] = useState("");
    const [topics, setTopics] = useState([]);
    const [questions, setQuestions] = useState([]);
    const [answers, setAnswers] = useState({});
    const [loading, setLoading] = useState(false);
    const [submitted, setSubmitted] = useState(false);
    const [score, setScore] = useState(0);

    useEffect(() => {
        const savedTopics = JSON.parse(localStorage.getItem("chatTopics")) || [];
        if (savedTopics.length > 0) {
            setTopics(savedTopics);
        } else {
            console.warn("No previous topics found in localStorage.");
        }
    }, []);

    const fetchAIQuestions = async () => {
        if (!topic) {
            alert("Please select a topic first!");
            return;
        }

        setLoading(true);
        setQuestions([]);
        setAnswers({});
        setSubmitted(false);
        setScore(0);

        console.log("Fetching questions for topic:", topic);

        try {
            const response = await fetch("http://localhost:5000/generate-questions", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ topics: [topic] }), // ✅ Sending topics as an array
            });

            console.log("Response status:", response.status);

            if (!response.ok) {
                throw new Error(`HTTP error! Status: ${response.status}`);
            }

            const data = await response.json();
            console.log("Received questions:", data);

            if (data.topics?.length > 0 && Array.isArray(data.topics[0].questions)) {
                setQuestions(data.topics[0].questions);
            } else {
                alert("No questions generated. Try another topic.");
            }
        } catch (error) {
            console.error("Error fetching AI questions:", error);
            alert("Failed to fetch questions. Please check the console for more details.");
        } finally {
            setLoading(false);
        }
    };

    const handleAnswerSelect = (questionIndex, selectedOption) => {
        setAnswers((prevAnswers) => ({
            ...prevAnswers,
            [questionIndex]: selectedOption,
        }));
    };

    const handleSubmit = () => {
        let newScore = 0;
        questions.forEach((q, index) => {
            if (answers[index] === q.correct) { // ✅ Accessing correct answer properly
                newScore++;
            }
        });
        setScore(newScore);
        setSubmitted(true);
    };

    return (
        <div className="test-container">
            <div className="questions-section">
                <h2>📝 AI Generated Quiz</h2>

                <div className="previous-topics">
                    <select
                        value={topic}
                        onChange={(e) => setTopic(e.target.value)}
                        className="topic-btn"
                    >
                        <option value="">Select a Topic</option>
                        {topics.length > 0 ? (
                            topics.map((t, index) => (
                                <option key={index} value={t}>
                                    {t}
                                </option>
                            ))
                        ) : (
                            <option disabled>No topics found</option>
                        )}
                    </select>

                    <button
                        onClick={fetchAIQuestions}
                        disabled={loading || !topic}
                        className="topic-btn"
                    >
                        {loading ? "Generating..." : "Generate Questions"}
                    </button>
                </div>

                {questions.length > 0 && (
                    <div className="questions-scrollable">
                        <h3>🧐 Questions</h3>
                        {questions.map((q, index) => (
                            <div key={index} className="question">
                                <strong>
                                    {index + 1}. {q.question}
                                </strong>
                                <div>
                                    {Object.entries(q.options).map(([key, option]) => (
                                        <label key={key} className="option-btn">
                                            <input
                                                type="radio"
                                                name={`question-${index}`}
                                                value={key}
                                                checked={answers[index] === key}
                                                onChange={() => handleAnswerSelect(index, key)}
                                                disabled={submitted}
                                            />
                                            {option}
                                        </label>
                                    ))}
                                </div>
                            </div>
                        ))}
                    </div>
                )}

                {questions.length > 0 && !submitted && (
                    <button onClick={handleSubmit} className="submit-btn">
                        Submit Answers
                    </button>
                )}

                {submitted && (
                    <div className="score-section">
                        <h3>🎯 Scorecard</h3>
                        <p>
                            <strong>Your Score: {score} / {questions.length}</strong>
                        </p>
                        <h4>✅ Correct Answers:</h4>
                        <ul>
                            {questions.map((q, index) => (
                                <li key={index}>
                                    {q.question} - <strong>{q.options[q.correct]}</strong>
                                </li>
                            ))}
                        </ul>
                    </div>
                )}
            </div>
        </div>
    );
};

export default Test;
